     1→syntax = "proto3";
     2→
     3→package spec_oracle;
     4→
     5→service SpecOracle {
     6→  // Node operations
     7→  rpc AddNode(AddNodeRequest) returns (AddNodeResponse);
     8→  rpc GetNode(GetNodeRequest) returns (GetNodeResponse);
     9→  rpc ListNodes(ListNodesRequest) returns (ListNodesResponse);
    10→  rpc RemoveNode(RemoveNodeRequest) returns (RemoveNodeResponse);
    11→
    12→  // Edge operations
    13→  rpc AddEdge(AddEdgeRequest) returns (AddEdgeResponse);
    14→  rpc ListEdges(ListEdgesRequest) returns (ListEdgesResponse);
    15→  rpc RemoveEdge(RemoveEdgeRequest) returns (RemoveEdgeResponse);
    16→
    17→  // Query and analysis
    18→  rpc Query(QueryRequest) returns (QueryResponse);
    19→  rpc DetectContradictions(DetectContradictionsRequest) returns (DetectContradictionsResponse);
    20→  rpc DetectOmissions(DetectOmissionsRequest) returns (DetectOmissionsResponse);
    21→  rpc DetectLayerInconsistencies(DetectLayerInconsistenciesRequest) returns (DetectLayerInconsistenciesResponse);
    22→
    23→  // Terminology resolution
    24→  rpc ResolveTerminology(ResolveTerminologyRequest) returns (ResolveTerminologyResponse);
    25→
    26→  // Layer-aware operations
    27→  rpc FilterByLayer(FilterByLayerRequest) returns (FilterByLayerResponse);
    28→  rpc FindFormalizations(FindFormalizationsRequest) returns (FindFormalizationsResponse);
    29→
    30→  // Semantic normalization
    31→  rpc FindRelatedTerms(FindRelatedTermsRequest) returns (FindRelatedTermsResponse);
    32→  rpc DetectPotentialSynonyms(DetectPotentialSynonymsRequest) returns (DetectPotentialSynonymsResponse);
    33→
    34→  // Executable contracts
    35→  rpc GenerateContractTemplate(GenerateContractTemplateRequest) returns (GenerateContractTemplateResponse);
    36→  rpc GetTestCoverage(GetTestCoverageRequest) returns (GetTestCoverageResponse);
    37→
    38→  // Graded compliance
    39→  rpc CalculateCompliance(CalculateComplianceRequest) returns (CalculateComplianceResponse);
    40→  rpc GetComplianceReport(GetComplianceReportRequest) returns (GetComplianceReportResponse);
    41→
    42→  // Temporal queries
    43→  rpc QueryAtTimestamp(QueryAtTimestampRequest) returns (QueryAtTimestampResponse);
    44→  rpc DiffTimestamps(DiffTimestampsRequest) returns (DiffTimestampsResponse);
    45→  rpc GetNodeHistory(GetNodeHistoryRequest) returns (GetNodeHistoryResponse);
    46→  rpc GetComplianceTrend(GetComplianceTrendRequest) returns (GetComplianceTrendResponse);
    47→
    48→  // Inter-universe consistency (conversation.md U, D, A, f implementation)
    49→  rpc DetectInterUniverseInconsistencies(DetectInterUniverseInconsistenciesRequest) returns (DetectInterUniverseInconsistenciesResponse);
    50→  rpc SetNodeUniverse(SetNodeUniverseRequest) returns (SetNodeUniverseResponse);
    51→
    52→  // Automatic relationship inference
    53→  rpc InferAllRelationships(InferAllRelationshipsRequest) returns (InferAllRelationshipsResponse);
    54→
    55→  // AI-powered relationship inference (cross-layer semantic matching)
    56→  rpc InferAllRelationshipsWithAi(InferAllRelationshipsWithAiRequest) returns (InferAllRelationshipsResponse);
    57→}
    58→
    59→// --- Node types ---
    60→
    61→message SpecNode {
    62→  string id = 1;
    63→  string content = 2;
    64→  SpecNodeKind kind = 3;
    65→  map<string, string> metadata = 4;
    66→  int64 created_at = 5;
    67→  int64 modified_at = 6;
    68→  uint32 formality_layer = 7;  // 0=natural, 1=structured, 2=formal, 3=executable
    69→}
    70→
    71→enum SpecNodeKind {
    72→  SPEC_NODE_KIND_UNSPECIFIED = 0;
    73→  ASSERTION = 1;       // A concrete claim about behavior
    74→  CONSTRAINT = 2;      // A universal constraint (invariant)
    75→  SCENARIO = 3;        // An existential requirement (a path that must exist)
    76→  DEFINITION = 4;      // A term definition
    77→  DOMAIN = 5;          // A domain boundary declaration
    78→}
    79→
    80→// --- Edge types ---
    81→
    82→message SpecEdge {
    83→  string id = 1;
    84→  string source_id = 2;
    85→  string target_id = 3;
    86→  SpecEdgeKind kind = 4;
    87→  map<string, string> metadata = 5;
    88→  int64 created_at = 6;
    89→}
    90→
    91→enum SpecEdgeKind {
    92→  SPEC_EDGE_KIND_UNSPECIFIED = 0;
    93→  REFINES = 1;         // Target refines source (is more specific)
    94→  DEPENDS_ON = 2;      // Source depends on target
    95→  CONTRADICTS = 3;     // Source contradicts target
    96→  DERIVES_FROM = 4;    // Source is derived from target
    97→  SYNONYM = 5;         // Source and target are synonymous terms
    98→  COMPOSES = 6;        // Source composes with target into a higher-level spec
    99→  FORMALIZES = 7;      // Target is a more formal version of source
   100→  TRANSFORM = 8;       // Function f: maps spec from source universe to target universe
   101→}
