     1→//! Unified command dispatcher for standalone and server modes
     2→//!
     3→//! This module contains the command dispatch logic, separating it from
     4→//! the CLI parsing layer in main.rs. This achieves the separation of
     5→//! concerns required by the specification.
     6→
     7→use crate::proto::spec_oracle_client::SpecOracleClient;
     8→use crate::proto::{self, SpecEdgeKind, SpecNodeKind};
     9→use crate::utils::*;
    10→use crate::presentation::formatter::*;
    11→use crate::ApiCommands;
    12→use spec_core::{Store, NodeKind as CoreNodeKind};
    13→use std::collections::HashMap;
    14→use std::path::PathBuf;
    15→use tonic::Request;
    16→
    17→/// Dispatch commands in standalone mode (direct file access, no server)
    18→pub async fn dispatch_standalone(
    19→    command: crate::Commands,
    20→    store: Store,
    21→) -> Result<(), Box<dyn std::error::Error>> {
    22→    use crate::commands;
    23→
    24→    let mut store = store;
    25→
    26→    match command {
    27→        crate::Commands::Init { path: _ } => {
    28→            // Init command doesn't need existing spec file
    29→            eprintln!("Error: Init command should not reach standalone mode");
    30→            return Ok(());
    31→        }
    32→        crate::Commands::Migrate { source, target } => {
    33→            commands::execute_migrate(source, target)?;
    34→            return Ok(());
    35→        }
    36→        crate::Commands::Add { content, no_infer } => {
    37→            commands::execute_add_standalone(&mut store, content, no_infer)?;
    38→        }
    39→        crate::Commands::Api(api_cmd) => {
    40→            dispatch_api_standalone(&mut store, api_cmd)?;
    41→        }
    42→        crate::Commands::ListNodes { kind, layer, status, full, limit, offset } => {
    43→            dispatch_list_nodes_standalone(&store, kind, layer, status.clone(), full, limit, offset)?;
    44→        }
    45→        crate::Commands::DetectContradictions => {
    46→            commands::execute_contradictions_standalone(&store)?;
    47→        }
    48→        crate::Commands::DetectOmissions => {
    49→            commands::execute_omissions_standalone(&store)?;
    50→        }
    51→        crate::Commands::Check => {
    52→            let exit_code = commands::execute_check_standalone(&store)?;
    53→            std::process::exit(exit_code);
    54→        }
    55→        crate::Commands::Summary => {
    56→            commands::execute_summary_standalone(&store)?;
    57→        }
    58→        crate::Commands::ExportDot { output, layer, metadata } => {
    59→            commands::execute_export_dot_standalone(&store, output, layer, metadata)?;
    60→        }
    61→        crate::Commands::Find { query, layer, status, max } => {
    62→            commands::execute_find_standalone(&store, &query, layer, status.clone(), max).await?;
    63→        }
    64→        crate::Commands::GetNode { id } => {
    65→            eprintln!("⚠️  WARNING: 'spec get-node' is deprecated. Use 'spec api get-node' instead.");
    66→            eprintln!("   The command will still work but may be removed in a future version.\n");
    67→            commands::api::execute_get_node_standalone(&store, id)?;
    68→        }
    69→        crate::Commands::Trace { id, depth } => {
    70→            commands::execute_trace_standalone(&store, &id, depth).await?;
    71→        }
    72→        crate::Commands::VerifyLayers => {
    73→            commands::execute_verify_layers_standalone(&store)?;
    74→        }
    75→        crate::Commands::ProveConsistency { spec_a, spec_b } => {
    76→            commands::execute_prove_consistency_standalone(&store, spec_a, spec_b)?;
    77→        }
    78→        crate::Commands::ProveSatisfiability { spec } => {
    79→            commands::execute_prove_satisfiability_standalone(&store, spec)?;
    80→        }
    81→        crate::Commands::InspectModel { verbose } => {
    82→            commands::execute_inspect_model_standalone(&store, verbose)?;
    83→        }
    84→        crate::Commands::ConstructU0 { execute, verbose } => {
    85→            commands::execute_construct_u0_standalone(&mut store, execute, verbose)?;
    86→        }
    87→        crate::Commands::CleanupLowQuality { execute } => {
    88→            commands::execute_cleanup_low_quality_standalone(&mut store, execute)?;
    89→        }
    90→        crate::Commands::AddEdge { source, target, kind } => {
    91→            eprintln!("⚠️  WARNING: 'spec add-edge' is deprecated. Use 'spec api add-edge' instead.");
    92→            eprintln!("   The command will still work but may be removed in a future version.\n");
    93→            commands::api::execute_add_edge_standalone(&mut store, source, target, kind)?;
    94→        }
    95→        crate::Commands::Extract { source, language, min_confidence } => {
    96→            commands::execute_extract_standalone(&mut store, source, language, min_confidence)?;
    97→        }
    98→        crate::Commands::InferRelationshipsAi { min_confidence, dry_run, limit, interactive } => {
    99→            commands::execute_infer_relationships_ai_standalone(&mut store, min_confidence, dry_run, limit, interactive)?;
   100→        }
   101→        crate::Commands::Archive { id } => {
   102→            commands::execute_archive(&mut store, id)?;
   103→        }
   104→        crate::Commands::Deprecate { id } => {
   105→            commands::execute_deprecate(&mut store, id)?;
   106→        }
   107→        crate::Commands::Activate { id } => {
   108→            commands::execute_activate(&mut store, id)?;
   109→        }
