   178→/// Dispatch list-nodes command in standalone mode (deprecated)
   179→fn dispatch_list_nodes_standalone(
   180→    store: &Store,
   181→    kind: Option<String>,
   182→    layer: Option<u8>,
   183→    status: Option<String>,
   184→    full: bool,
   185→    limit: Option<usize>,
   186→    offset: Option<usize>,
   187→) -> Result<(), Box<dyn std::error::Error>> {
   188→    eprintln!("⚠️  WARNING: 'spec list-nodes' is deprecated. Use 'spec api list-nodes' instead.");
   189→    eprintln!("   The command will still work but may be removed in a future version.\n");
   190→
   191→    let graph = store.load()?;
   192→    let kind_filter = kind.as_ref().map(|k| proto_to_core_kind(parse_node_kind(k)));
   193→    let mut nodes = graph.list_nodes(kind_filter);
   194→
   195→    // Apply layer filter if specified
   196→    if let Some(layer_filter) = layer {
   197→        nodes.retain(|n| n.formality_layer == layer_filter);
   198→    }
   199→
   200→    // Apply status filter if specified
   201→    if let Some(ref status_filter) = status {
   202→        nodes.retain(|n| {
   203→            let node_status = n.metadata.get("status")
   204→                .map(|s| s.as_str())
   205→                .unwrap_or("active");
   206→            node_status == status_filter.as_str()
   207→        });
   208→    }
   209→
   210→    // Summary mode (default)
   211→    if !full {
   212→        println!("📊 Specification Summary");
   213→        println!("Total: {} specifications", nodes.len());
   214→        println!();
   215→
   216→        // Group by formality layer
   217→        let mut by_layer = std::collections::HashMap::<u8, usize>::new();
   218→        for node in &nodes {
   219→            *by_layer.entry(node.formality_layer).or_insert(0) += 1;
   220→        }
   221→
   222→        println!("By Formality Layer:");
   223→        for layer_num in 0..=3 {
   224→            if let Some(&count) = by_layer.get(&layer_num) {
   225→                let layer_label = format_formality_layer(layer_num);
   226→                let layer_name = match layer_num {
   227→                    0 => "Natural Language Requirements",
   228→                    1 => "Formal Specifications",
   229→                    2 => "Interface Definitions",
   230→                    3 => "Implementation",
   231→                    _ => "Unknown",
   232→                };
   233→                println!("  {}: {} ({} specs)", layer_label, layer_name, count);
   234→            }
   235→        }
   236→        println!();
   237→
   238→        // Group by kind
   239→        let mut by_kind = std::collections::HashMap::<String, usize>::new();
   240→        for node in &nodes {
   241→            let kind_str = match node.kind {
   242→                CoreNodeKind::Assertion => "Assertions".to_string(),
   243→                CoreNodeKind::Constraint => "Constraints".to_string(),
   244→                CoreNodeKind::Scenario => "Scenarios".to_string(),
   245→                CoreNodeKind::Definition => "Definitions".to_string(),
   246→                CoreNodeKind::Domain => "Domains".to_string(),
   247→            };
   248→            *by_kind.entry(kind_str).or_insert(0) += 1;
   249→        }
   250→
   251→        println!("By Kind:");
   252→        let mut kind_vec: Vec<_> = by_kind.iter().collect();
   253→        kind_vec.sort_by_key(|(k, _)| k.as_str());
   254→        for (kind, count) in kind_vec {
   255→            println!("  {}: {}", kind, count);
   256→        }
   257→        println!();
   258→
   259→        println!("💡 Use --full to see the complete list");
   260→        println!("💡 Use --layer <N> to filter by formality layer (0-3)");
   261→        println!("💡 Use --kind <type> to filter by kind");
   262→        return Ok(());
   263→    }
   264→
   265→    // Full mode with optional pagination
   266→    let offset_val = offset.unwrap_or(0);
   267→    let limit_val = limit.unwrap_or(nodes.len());
   268→    let end = std::cmp::min(offset_val + limit_val, nodes.len());
   269→    let page_nodes: Vec<_> = nodes.iter().skip(offset_val).take(limit_val).collect();
   270→
   271→    println!("Found {} node(s):", nodes.len());
   272→    if offset_val > 0 || limit.is_some() {
   273→        println!("Showing {} - {} of {}:", offset_val + 1, end, nodes.len());
   274→    }
   275→    println!();
   276→
   277→    for node in page_nodes {
   278→        let kind_str = match node.kind {
   279→            CoreNodeKind::Assertion => "assertion",
   280→            CoreNodeKind::Constraint => "constraint",
   281→            CoreNodeKind::Scenario => "scenario",
   282→            CoreNodeKind::Definition => "definition",
   283→            CoreNodeKind::Domain => "domain",
   284→        };
   285→        let layer_label = format_formality_layer(node.formality_layer);
   286→        println!(
   287→            "  [{}] [{}] {} - {}",
   288→            layer_label,
   289→            &node.id[..8],
   290→            kind_str,
   291→            node.content.chars().take(80).collect::<String>()
   292→        );
   293→    }
   294→
   295→    if end < nodes.len() {
   296→        println!();
   297→        println!("... and {} more (use --offset {} to see next page)", nodes.len() - end, end);
   298→    }
   299→
   300→    Ok(())
   301→}
