     1→/// High-level specification addition command
     2→///
     3→/// Automatically infers the specification kind and relationships,
     4→/// providing a user-friendly interface for adding specifications.
     5→
     6→use crate::proto;
     7→use crate::utils::*;
     8→use spec_core::{Store, NodeKind as CoreNodeKind};
     9→use std::collections::HashMap;
    10→use tonic::Request;
