    12→/// Execute the Add command in standalone mode
    13→pub fn execute_add_standalone(
    14→    store: &mut Store,
    15→    content: String,
    16→    no_infer: bool,
    17→) -> Result<(), Box<dyn std::error::Error>> {
    18→    println!("Adding specification: {}\n", content);
    19→
    20→    // Load graph
    21→    let mut graph = store.load()?;
    22→
    23→    // Infer kind
    24→    let kind = infer_spec_kind(&content);
    25→    println!("  Inferred kind: {}", kind);
    26→
    27→    // Add node
    28→    let proto_kind = parse_node_kind(&kind);
    29→    let core_kind = proto_to_core_kind(proto_kind);
    30→    let node = graph.add_node(content.clone(), core_kind, HashMap::new());
    31→    let node_id = node.id.clone();
    32→
    33→    println!("  ✓ Created specification [{}]", &node_id[..8]);
    34→
    35→    // Auto-infer relationships (unless disabled)
    36→    if !no_infer {
    37→        println!("\n  🔗 Auto-inferring relationships...");
    38→        let report = graph.auto_connect_node(&node_id);
    39→
    40→        if report.edges_created > 0 {
    41→            println!("  ✓ Created {} automatic relationship(s)", report.edges_created);
    42→        }
    43→
    44→        if !report.suggestions.is_empty() {
    45→            println!("  💡 {} medium-confidence suggestion(s) (use 'spec trace {}' to view)",
    46→                report.suggestions.len(), &node_id[..8]);
    47→        }
    48→
    49→        if report.edges_created == 0 && report.suggestions.is_empty() {
    50→            println!("  ℹ️  No automatic relationships found");
    51→            println!("     (This specification may be a new domain or highly unique)");
    52→        }
    53→    }
    54→
    55→    // Save graph
    56→    store.save(&graph)?;
    57→
    58→    println!("\n✓ Specification added successfully");
    59→    println!("  ID: {}", node_id);
    60→    println!("  Use 'spec trace {}' to view relationships", &node_id[..8]);
    61→
    62→    Ok(())
    63→}
