    65→/// Execute the Add command in server mode
    66→pub async fn execute_add_server(
    67→    client: &mut proto::spec_oracle_client::SpecOracleClient<tonic::transport::Channel>,
    68→    content: String,
    69→    no_infer: bool,
    70→) -> Result<(), Box<dyn std::error::Error>> {
    71→    println!("Adding specification: {}\n", content);
    72→
    73→    // Infer kind from content
    74→    let kind = infer_spec_kind(&content);
    75→    println!("  Inferred kind: {}", kind);
    76→
    77→    // Create the node
    78→    let resp = client
    79→        .add_node(Request::new(proto::AddNodeRequest {
    80→            content: content.clone(),
    81→            kind: parse_node_kind(&kind).into(),
    82→            metadata: HashMap::new(),
    83→        }))
    84→        .await?;
    85→    let node = resp.into_inner().node.unwrap();
    86→    let node_id = node.id.clone();
    87→
    88→    println!("  ✓ Created specification [{}]", &node_id[..8]);
    89→
    90→    if !no_infer {
    91→        // Find related specifications
    92→        println!("\n  Searching for related specifications...");
    93→        let query_resp = client
    94→            .query(Request::new(proto::QueryRequest {
    95→                natural_language_query: content.clone(),
    96→            }))
    97→            .await?;
    98→        let matches = query_resp.into_inner().matching_nodes;
    99→
   100→        if !matches.is_empty() {
   101→            println!("  Found {} related specification(s)", matches.len());
   102→            println!("  Creating relationships...");
   103→
   104→            let mut created = 0;
   105→            for related_node in matches.iter().take(5) {
   106→                if related_node.id != node_id {
   107→                    match client
   108→                        .add_edge(Request::new(proto::AddEdgeRequest {
   109→                            source_id: node_id.clone(),
   110→                            target_id: related_node.id.clone(),
   111→                            kind: proto::SpecEdgeKind::Refines.into(),
   112→                            metadata: HashMap::new(),
   113→                        }))
   114→                        .await
   115→                    {
   116→                        Ok(_) => created += 1,
   117→                        Err(_) => {}, // Edge already exists or other error
   118→                    }
   119→                }
   120→            }
   121→
   122→            if created > 0 {
   123→                println!("  ✓ Created {} automatic relationship(s)", created);
   124→            }
   125→        } else {
   126→            println!("  ℹ️  No related specifications found");
   127→        }
   128→    }
   129→
   130→    println!("\n✓ Specification added successfully");
   131→    println!("  ID: {}", node_id);
   132→
   133→    Ok(())
   134→}
