   136→/// Unified entry point for the Add command
   137→pub fn execute_add(
   138→    content: String,
   139→    no_infer: bool,
   140→    standalone_mode: bool,
   141→    store: Option<&mut Store>,
   142→    client: Option<&mut proto::spec_oracle_client::SpecOracleClient<tonic::transport::Channel>>,
   143→    runtime: Option<&tokio::runtime::Runtime>,
   144→) -> Result<(), Box<dyn std::error::Error>> {
   145→    if standalone_mode {
   146→        if let Some(store) = store {
   147→            execute_add_standalone(store, content, no_infer)
   148→        } else {
   149→            Err("Standalone mode requires a FileStore".into())
   150→        }
   151→    } else {
   152→        if let (Some(client), Some(rt)) = (client, runtime) {
   153→            rt.block_on(execute_add_server(client, content, no_infer))
   154→        } else {
   155→            Err("Server mode requires a client and runtime".into())
   156→        }
   157→    }
   158→}
