     1→/// Domain: The region that a specification actually covers
     2→///
     3→/// D represents "what this specification is about" - the subset of the universe
     4→/// that the specification intends to govern.
     5→///
     6→/// Gap detection: D \ D_S (intended domain minus actually specified domain)
     7→///
     8→/// ## 3-Layer Structure (Phase A: Minimization)
     9→/// - Layer 1: Identifier (`id`)
    10→/// - Layer 2: Proof Data (`proof_data`) - formal domain boundaries, coverage tracking
    11→/// - Layer 3: Metadata (`meta`) - human-readable info, organizational structure
    12→use serde::{Deserialize, Serialize};
    13→use super::{DomainId, DomainMetadata, DomainSet};
    14→use crate::formal::universe::UniverseId;
    15→use crate::formal::constraint::Constraint;
    16→use crate::formal::{SpecSet, MetadataKey};
    17→
    18→#[derive(Debug, Clone, Serialize, Deserialize)]
    19→pub struct Domain {
    20→    /// Layer 1: Unique identifier for this domain
    21→    pub id: DomainId,
    22→
    23→    // OLD FIELDS (deprecated, for migration compatibility)
    24→    /// Human-readable name (DEPRECATED: use meta.name)
    25→    #[serde(skip_serializing_if = "Option::is_none")]
    26→    pub name: Option<String>,
    27→
    28→    /// What this domain covers (DEPRECATED: use meta.description)
    29→    #[serde(skip_serializing_if = "Option::is_none")]
    30→    pub description: Option<String>,
    31→
    32→    /// The universe this domain belongs to (DEPRECATED: use meta.universe_id)
    33→    #[serde(skip_serializing_if = "Option::is_none")]
    34→    pub universe_id: Option<UniverseId>,
    35→
    36→    /// Specifications that cover this domain (DEPRECATED: use proof_data.covered_by)
    37→    #[serde(skip_serializing_if = "Option::is_none")]
    38→    pub covered_by: Option<SpecSet>,
    39→
    40→    /// Sub-domains (DEPRECATED: use meta.subdomains)
    41→    #[serde(skip_serializing_if = "Option::is_none")]
    42→    pub subdomains: Option<DomainSet>,
    43→
    44→    /// Metadata for extensibility (DEPRECATED: use meta)
    45→    #[serde(skip_serializing_if = "Option::is_none")]
    46→    pub metadata: Option<DomainMetadata>,
    47→
    48→    // NEW FIELDS (preferred)
    49→    /// Layer 2: Proof-essential data (constraints, coverage)
    50→    #[serde(skip_serializing_if = "Option::is_none")]
    51→    pub proof_data: Option<DomainProofData>,
    52→
    53→    /// Layer 3: Metadata (name, description, organizational structure)
    54→    #[serde(skip_serializing_if = "Option::is_none")]
    55→    pub meta: Option<DomainMetadata>,
    56→}
    57→
    58→/// Layer 2: Proof-essential data for Domain
    59→///
    60→/// Contains only the data needed for formal verification and proofs.
    61→/// The Prover should only access this layer, never metadata.
    62→#[derive(Debug, Clone, Serialize, Deserialize)]
    63→pub struct DomainProofData {
    64→    /// Formal domain boundary constraints (NEW: for completeness proofs)
    65→    /// When empty: Domain is not formalized (graceful degradation)
    66→    /// When present: Enables formal proofs about domain coverage (D ⊆ D_S)
    67→    pub constraints: Vec<Constraint>,
    68→
