    20→#[derive(Debug, Clone, Serialize, Deserialize)]
    21→pub struct AdmissibleSet {
    22→    /// Layer 1: The specification that defines this admissible set
    23→    pub spec_id: SpecId,
    24→
    25→    // OLD FIELDS (deprecated, for migration compatibility)
    26→    /// The universe this admissible set belongs to (DEPRECATED: use meta.universe_id)
    27→    #[serde(skip_serializing_if = "Option::is_none")]
    28→    pub universe_id: Option<UniverseId>,
    29→
    30→    /// Constraints that define membership (DEPRECATED: use proof_data.constraints)
    31→    #[serde(skip_serializing_if = "Option::is_none")]
    32→    pub constraints: Option<Vec<Constraint>>,
    33→
    34→    /// Known contradictions (DEPRECATED: use proof_data.contradicts)
    35→    #[serde(skip_serializing_if = "Option::is_none")]
    36→    pub contradicts: Option<SpecSet>,
    37→
    38→    /// Metadata for extensibility (DEPRECATED: use meta)
    39→    #[serde(skip_serializing_if = "Option::is_none")]
    40→    pub metadata: Option<Metadata>,
    41→
    42→    // NEW FIELDS (preferred)
    43→    /// Layer 2: Proof-essential data (constraints, contradictions)
    44→    #[serde(skip_serializing_if = "Option::is_none")]
    45→    pub proof_data: Option<AdmissibleSetProofData>,
    46→
    47→    /// Layer 3: Metadata (organizational info)
    48→    #[serde(skip_serializing_if = "Option::is_none")]
    49→    pub meta: Option<AdmissibleSetMetadata>,
    50→}
    51→
    52→/// Layer 2: Proof-essential data for AdmissibleSet
    53→///
    54→/// Contains only the data needed for formal verification and proofs.
    55→/// The Prover should only access this layer, never metadata.
    56→#[derive(Debug, Clone, Serialize, Deserialize)]
    57→pub struct AdmissibleSetProofData {
    58→    /// Constraints that define membership in this set
    59→    pub constraints: Vec<Constraint>,
    60→
