    62→    pub contradicts: SpecSet,
    63→}
    64→
    65→/// Layer 3: Metadata for AdmissibleSet
    66→///
    67→/// Contains human-readable and organizational information.
    68→/// NOT used in formal proofs.
    69→#[derive(Debug, Clone, Serialize, Deserialize)]
    70→pub struct AdmissibleSetMetadata {
    71→    /// The universe this admissible set belongs to (organizational)
    72→    pub universe_id: UniverseId,
    73→
    74→    /// Extensible metadata
