     6→/// Execute Query command in standalone mode
     7→pub async fn execute_query_standalone(
     8→    store: &Store,
     9→    query: &str,
    10→    ai: bool,
    11→) -> Result<(), Box<dyn std::error::Error>> {
    12→    let search_query = if ai {
    13→        println!("Enhancing query with AI...");
    14→        handle_ai_query(query, "claude").await?
    15→    } else {
    16→        query.to_string()
    17→    };
    18→
    19→    // Load from store and convert to repository
    20→    let spec_graph = store.load()?;
    21→    let graph = SpecRepository::from_spec_graph(&spec_graph);
    22→
    23→    // Search for matching specifications
    24→    let results = graph.search(&search_query);
    25→
    26→    if results.is_empty() {
    27→        println!("No specifications found matching '{}'", search_query);
    28→        println!("\nTry:");
    29→        println!("  - Using different keywords");
    30→        println!("  - Broadening your search");
    31→        println!("  - Using 'spec list-nodes' to see all specifications");
    32→    } else {
    33→        println!("Found {} specification(s) matching '{}':", results.len(), search_query);
    34→        println!();
    35→
    36→        for node in &results {
    37→            let layer_label = format_formality_layer(node.formality_layer);
    38→            let kind_str = match node.kind {
    39→                spec_core::NodeKind::Assertion => "assertion",
