    42→                spec_core::NodeKind::Definition => "definition",
    43→                spec_core::NodeKind::Domain => "domain",
    44→            };
    45→
    46→            println!("  [{}] [{}] {} - {}",
    47→                layer_label,
    48→                &node.id[..8],
    49→                kind_str,
    50→                node.content
    51→            );
    52→        }
    53→    }
    54→
    55→    Ok(())
    56→}
