     1→use crate::proto::{self, spec_oracle_client::SpecOracleClient};
     2→use crate::{format_formality_layer};
     3→use tonic::Request;
     4→use spec_core::{Store, NodeKind as CoreNodeKind, SpecRepository};
     5→
     6→/// Execute Find command in standalone mode
     7→pub async fn execute_find_standalone(
     8→    store: &Store,
     9→    query: &str,
    10→    layer: Option<u32>,
    11→    status: Option<String>,
    12→    max: u32,
    13→) -> Result<(), Box<dyn std::error::Error>> {
    14→    // Load from store and convert to repository
    15→    let spec_graph = store.load()?;
    16→    let graph = SpecRepository::from_spec_graph(&spec_graph);
    17→
    18→    // Search for matching specifications
    19→    let mut results = graph.search(query);
    20→
    21→    // Filter by layer if specified
    22→    if let Some(layer_num) = layer {
    23→        results.retain(|node| {
    24→            if let Some(layer_str) = node.metadata.get("formality_layer") {
    25→                layer_str.parse::<u32>().ok() == Some(layer_num)
    26→            } else {
    27→                node.formality_layer as u32 == layer_num
    28→            }
    29→        });
    30→    }
    31→
    32→    // Filter by status if specified
    33→    if let Some(ref status_filter) = status {
    34→        results.retain(|node| {
    35→            let node_status = node.metadata.get("status")
    36→                .map(|s| s.as_str())
    37→                .unwrap_or("active");
    38→            node_status == status_filter.as_str()
    39→        });
    40→    }
    41→
    42→    // Limit results
    43→    let max_results = max as usize;
    44→    if results.len() > max_results {
    45→        results.truncate(max_results);
    46→    }
    47→
    48→    if results.is_empty() {
    49→        println!("No specifications found matching '{}'", query);
    50→        println!("\nTry:");
    51→        println!("  - Using different keywords");
    52→        println!("  - Broadening your search");
    53→        println!("  - Using 'spec list-nodes' to see all specifications");
    54→    } else {
    55→        println!("Found {} specification(s) matching '{}':", results.len(), query);
    56→        println!();
    57→
    58→        for (i, node) in results.iter().enumerate() {
    59→            let kind_str = match node.kind {
    60→                CoreNodeKind::Assertion => "assertion",
    61→                CoreNodeKind::Constraint => "constraint",
    62→                CoreNodeKind::Scenario => "scenario",
    63→                CoreNodeKind::Definition => "definition",
    64→                CoreNodeKind::Domain => "domain",
    65→            };
    66→            let layer_str = if let Some(l) = node.metadata.get("formality_layer") {
    67→                format!(" [U{}]", l)
    68→            } else {
    69→                format!(" [U{}]", node.formality_layer)
    70→            };
    71→            println!("  {}. [{}]{} {} - {}",
    72→                i + 1,
    73→                &node.id[..8],
    74→                layer_str,
    75→                kind_str,
    76→                node.content
    77→            );
    78→        }
    79→
    80→        // Show active filters
    81→        let mut filters = Vec::new();
    82→        if let Some(layer_num) = layer {
    83→            filters.push(format!("layer U{}", layer_num));
    84→        }
    85→        if let Some(ref status_filter) = status {
    86→            filters.push(format!("status: {}", status_filter));
    87→        }
    88→        if !filters.is_empty() {
    89→            println!("\n(Filtered by: {})", filters.join(", "));
    90→        }
    91→    }
    92→
    93→    Ok(())
    94→}
    95→
    96→/// Execute Find command in server mode
    97→pub async fn execute_find_server(
    98→    client: &mut SpecOracleClient<tonic::transport::Channel>,
    99→    query: &str,
   100→    layer: Option<u32>,
   101→    status: Option<String>,
   102→    max: u32,
   103→) -> Result<(), Box<dyn std::error::Error>> {
   104→    // Use Query RPC since there's no dedicated Find RPC
   105→    let search_resp = client
   106→        .query(Request::new(proto::QueryRequest {
   107→            natural_language_query: query.to_string(),
   108→        }))
   109→        .await?;
   110→    let mut results = search_resp.into_inner().matching_nodes;
   111→
   112→    // Filter by layer if specified
   113→    if let Some(layer_num) = layer {
   114→        results.retain(|node| {
   115→            if let Some(layer_str) = node.metadata.get("formality_layer") {
   116→                layer_str.parse::<u32>().ok() == Some(layer_num)
   117→            } else {
   118→                node.formality_layer == layer_num
   119→            }
   120→        });
   121→    }
   122→
   123→    // Filter by status if specified
   124→    if let Some(ref status_filter) = status {
   125→        results.retain(|node| {
   126→            let node_status = node.metadata.get("status")
   127→                .map(|s| s.as_str())
   128→                .unwrap_or("active");
   129→            node_status == status_filter.as_str()
   130→        });
   131→    }
   132→
   133→    // Limit results
   134→    let max_results = max as usize;
   135→    if results.len() > max_results {
   136→        results.truncate(max_results);
   137→    }
   138→
   139→    if results.is_empty() {
   140→        println!("No specifications found matching '{}'", query);
   141→    } else {
   142→        println!("Found {} specification(s) matching '{}':", results.len(), query);
   143→        println!();
   144→
   145→        for (i, node) in results.iter().enumerate() {
   146→            let layer_label = format_formality_layer(node.formality_layer as u8);
   147→            println!("  {}. [{}] [{}] {} - {}",
   148→                i + 1,
   149→                layer_label,
   150→                &node.id[..8],
   151→                crate::node_kind_name(node.kind),
   152→                node.content
   153→            );
   154→        }
   155→
   156→        // Show active filters
   157→        let mut filters = Vec::new();
   158→        if let Some(layer_num) = layer {
   159→            filters.push(format!("layer U{}", layer_num));
   160→        }
   161→        if let Some(ref status_filter) = status {
   162→            filters.push(format!("status: {}", status_filter));
   163→        }
   164→        if !filters.is_empty() {
   165→            println!("\n(Filtered by: {})", filters.join(", "));
   166→        }
   167→    }
   168→
   169→    Ok(())
   170→}
