     1→/// Projection: The composition of observation and extraction
     2→///
     3→/// proj_i = obs_i >> extract_i
     4→///
     5→/// A projection takes a RootSpace, observes it through a specific layer lens
     6→/// to produce an ArtifactSpace, then extracts typed intermediate representations.
     7→///
     8→/// This implements the core composition from paper §2.6:
     9→///   Γ_root →[obs_i]→ Γ_i →[extract_i]→ β_i
    10→///
    11→/// Where:
    12→///   - obs_i: RootSpace → ArtifactSpace (layer-specific observation)
    13→///   - extract_i: ArtifactSpace → Vec<T> (typed extraction from artifacts)
    14→///   - proj_i: the composition obs_i >> extract_i
    15→use crate::formal::projection::{ArtifactSpace, Observer, RootSpace};
    16→use crate::formal::universe::UniverseId;
    17→
    18→/// Extractor trait: Γ_i → Option<β_i>
    19→///
    20→/// Extracts typed intermediate representations from an artifact space.
    21→/// Each extractor is specialized for a particular output type T (the β_i).
    22→///
    23→/// Returns a Vec<T> because a single artifact space may yield multiple
    24→/// extracted items (e.g., multiple spec fragments from a code file).
    25→pub trait Extractor<T> {
    26→    /// Extract typed representations from an artifact space.
    27→    ///
    28→    /// Given an observed artifact space Γ_i, produces a vector of
    29→    /// extracted items of type T. Returns an empty Vec if no items
    30→    /// can be extracted (rather than failing).
    31→    fn extract(&self, artifact: &ArtifactSpace) -> Vec<T>;
    32→}
    33→
    34→/// Projection: composes an Observer and an Extractor into a single operation.
    35→///
    36→/// ```text
    37→/// RootSpace →[observer]→ ArtifactSpace →[extractor]→ Vec<T>
    38→/// ```
    39→///
    40→/// The target_layer determines which universe layer the observer focuses on.
    41→pub struct Projection<O, E> {
    42→    /// The observer that produces an ArtifactSpace from a RootSpace
    43→    pub observer: O,
    44→
    45→    /// The extractor that produces typed output from an ArtifactSpace
    46→    pub extractor: E,
    47→
    48→    /// The target universe layer for observation (e.g., U1, U2, U3)
    49→    pub target_layer: UniverseId,
    50→}
    51→
    52→impl<O, E> Projection<O, E>
    53→where
    54→    O: Observer,
    55→{
    56→    /// Create a new projection for a specific target layer.
    57→    pub fn new(observer: O, extractor: E, target_layer: UniverseId) -> Self {
    58→        Self {
    59→            observer,
    60→            extractor,
    61→            target_layer,
    62→        }
    63→    }
    64→
    65→    /// Execute the projection: obs >> extract
    66→    ///
    67→    /// 1. Calls observer.observe(root, &target_layer) to get Option<ArtifactSpace>
    68→    /// 2. If Some(artifact), calls extractor.extract(&artifact) to get Vec<T>
    69→    /// 3. If None, returns empty Vec
    70→    /// 4. Returns the extracted items
    71→    pub fn project<T>(&self, root: &RootSpace) -> Vec<T>
    72→    where
    73→        E: Extractor<T>,
    74→    {
    75→        match self.observer.observe(root, &self.target_layer) {
    76→            Some(artifact) => self.extractor.extract(&artifact),
    77→            None => Vec::new(),
    78→        }
    79→    }
    80→}
    81→
    82→#[cfg(test)]
    83→mod tests {
    84→    use super::*;
    85→
    86→    /// A trivial observer for testing that returns an empty ArtifactSpace
    87→    struct StubObserver;
    88→
    89→    impl Observer for StubObserver {
    90→        fn observe(&self, _root: &RootSpace, _layer: &UniverseId) -> Option<ArtifactSpace> {
    91→            use crate::formal::projection::ArtifactKind;
    92→            Some(ArtifactSpace::from_text(
    93→                ArtifactKind::SourceCode,
    94→                String::new(),
    95→                "stub".to_string(),
    96→            ))
    97→        }
    98→
    99→        fn artifact_kind(&self) -> crate::formal::projection::ArtifactKind {
   100→            crate::formal::projection::ArtifactKind::SourceCode
   101→        }
   102→    }
   103→
   104→    /// A trivial extractor for testing that always returns an empty Vec
   105→    struct StubExtractor;
   106→
   107→    impl Extractor<String> for StubExtractor {
   108→        fn extract(&self, _artifact: &ArtifactSpace) -> Vec<String> {
   109→            Vec::new()
   110→        }
   111→    }
   112→
   113→    #[test]
   114→    fn projection_compose_returns_empty_for_stub() {
   115→        let proj = Projection::new(
   116→            StubObserver,
   117→            StubExtractor,
   118→            UniverseId::root(),
   119→        );
   120→        let root = RootSpace::new_artifact_bundle();
   121→        let result: Vec<String> = proj.project(&root);
   122→        assert!(result.is_empty());
   123→    }
   124→}
