    13→/// Execute AddNode API command in standalone mode
    14→pub fn execute_add_node_standalone(
    15→    store: &mut Store,
    16→    content: String,
    17→    kind: String,
    18→) -> Result<(), Box<dyn std::error::Error>> {
    19→    let mut graph = store.load()?;
    20→    let proto_kind = parse_node_kind(&kind);
    21→    let core_kind = proto_to_core_kind(proto_kind);
    22→    let node = graph.add_node(content.clone(), core_kind, HashMap::new());
    23→    let node_id = node.id.clone();
    24→    let node_content = node.content.clone();
    25→    let node_kind = node.kind;
    26→    store.save(&graph)?;
    27→    println!("Added node: {}", node_id);
    28→    println!("  Content: {}", node_content);
    29→    println!("  Kind: {:?}", node_kind);
    30→    Ok(())
    31→}
