     1→use crate::proto::{SpecEdgeKind, SpecNodeKind};
     2→use spec_core::NodeKind as CoreNodeKind;
     3→
     4→/// Parse node kind string to proto SpecNodeKind
     5→pub fn parse_node_kind(s: &str) -> SpecNodeKind {
     6→    match s.to_lowercase().as_str() {
     7→        "assertion" => SpecNodeKind::Assertion,
     8→        "constraint" => SpecNodeKind::Constraint,
     9→        "scenario" => SpecNodeKind::Scenario,
    10→        "definition" => SpecNodeKind::Definition,
    11→        "domain" => SpecNodeKind::Domain,
    12→        _ => SpecNodeKind::Assertion,
    13→    }
    14→}
    15→
    16→/// Parse edge kind string to proto SpecEdgeKind
    17→pub fn parse_edge_kind(s: &str) -> SpecEdgeKind {
    18→    match s.to_lowercase().as_str() {
    19→        "refines" => SpecEdgeKind::Refines,
    20→        "depends_on" | "depends-on" => SpecEdgeKind::DependsOn,
    21→        "contradicts" => SpecEdgeKind::Contradicts,
    22→        "derives_from" | "derives-from" => SpecEdgeKind::DerivesFrom,
    23→        "synonym" => SpecEdgeKind::Synonym,
    24→        "composes" => SpecEdgeKind::Composes,
    25→        "formalizes" => SpecEdgeKind::Formalizes,
    26→        "transform" => SpecEdgeKind::Transform,
    27→        _ => SpecEdgeKind::Refines,
    28→    }
    29→}
    30→
    31→/// Parse formality layer (after migration, just convert u8 to u32)
    32→pub fn parse_formality_layer(formality_layer: u8) -> u32 {
    33→    formality_layer as u32
    34→}
    35→
    36→/// Convert proto NodeKind to core NodeKind
    37→pub fn proto_to_core_kind(kind: SpecNodeKind) -> CoreNodeKind {
    38→    match kind {
    39→        SpecNodeKind::Assertion => CoreNodeKind::Assertion,
    40→        SpecNodeKind::Constraint => CoreNodeKind::Constraint,
    41→        SpecNodeKind::Scenario => CoreNodeKind::Scenario,
    42→        SpecNodeKind::Definition => CoreNodeKind::Definition,
    43→        SpecNodeKind::Domain => CoreNodeKind::Domain,
    44→        _ => CoreNodeKind::Assertion,
    45→    }
    46→}
    47→
    48→/// Convert proto node kind i32 to name string
    49→pub fn node_kind_name(k: i32) -> &'static str {
    50→    match SpecNodeKind::try_from(k) {
    51→        Ok(SpecNodeKind::Assertion) => "assertion",
    52→        Ok(SpecNodeKind::Constraint) => "constraint",
    53→        Ok(SpecNodeKind::Scenario) => "scenario",
    54→        Ok(SpecNodeKind::Definition) => "definition",
    55→        Ok(SpecNodeKind::Domain) => "domain",
    56→        _ => "unknown",
    57→    }
    58→}
    59→
    60→/// Convert proto edge kind i32 to name string
    61→pub fn edge_kind_name(k: i32) -> &'static str {
    62→    match SpecEdgeKind::try_from(k) {
    63→        Ok(SpecEdgeKind::Refines) => "refines",
    64→        Ok(SpecEdgeKind::DependsOn) => "depends_on",
    65→        Ok(SpecEdgeKind::Contradicts) => "contradicts",
    66→        Ok(SpecEdgeKind::DerivesFrom) => "derives_from",
    67→        Ok(SpecEdgeKind::Synonym) => "synonym",
    68→        Ok(SpecEdgeKind::Composes) => "composes",
    69→        Ok(SpecEdgeKind::Formalizes) => "formalizes",
    70→        Ok(SpecEdgeKind::Transform) => "transform",
    71→        _ => "unknown",
    72→    }
    73→}
    74→
    75→/// Infer specification kind from content using keyword patterns
    76→pub fn infer_spec_kind(content: &str) -> String {
    77→    let lower = content.to_lowercase();
    78→
    79→    // Domain indicators
    80→    if lower.starts_with("domain:") || lower.contains("domain boundary") {
    81→        return "domain".to_string();
    82→    }
    83→
    84→    // Definition indicators
    85→    if lower.contains(" is defined as ")
    86→        || lower.contains("definition:")
    87→        || lower.contains(" means ")
    88→        || lower.contains(" refers to ")
    89→    {
    90→        return "definition".to_string();
    91→    }
    92→
    93→    // Constraint indicators (universal invariants)
    94→    if (lower.contains("must") || lower.contains("shall") || lower.contains("required"))
    95→        && (lower.contains("always") || lower.contains("all") || lower.contains("every"))
    96→    {
    97→        return "constraint".to_string();
    98→    }
    99→
   100→    if lower.contains("invariant")
   101→        || lower.contains(" >= ")
   102→        || lower.contains(" <= ")
   103→        || lower.contains("not allowed")
   104→        || lower.contains("forbidden")
   105→    {
   106→        return "constraint".to_string();
   107→    }
   108→
   109→    // Scenario indicators (existential requirements, test cases)
   110→    if lower.starts_with("when ")
   111→        || lower.starts_with("given ")
   112→        || lower.starts_with("scenario:")
   113→        || lower.contains("should be able to")
   114→        || lower.contains("can ")
   115→        || lower.contains("test:")
   116→    {
   117→        return "scenario".to_string();
   118→    }
   119→
   120→    // Assertion indicators (concrete claims)
   121→    if lower.contains("returns")
   122→        || lower.contains("produces")
   123→        || lower.contains("outputs")
   124→        || lower.contains("implements")
   125→    {
   126→        return "assertion".to_string();
   127→    }
