    24→    #[serde(with = "super::serde_helpers::admissible_map_serde")]
    25→    pub admissible_sets: HashMap<SpecId, AdmissibleSet>,
    26→
    27→    /// All transform functions between universes (keyed by TransformId)
    28→    #[serde(with = "super::serde_helpers::transform_map_serde")]
    29→    pub transforms: HashMap<TransformId, TransformFunction>,
