    40→impl UDAFModel {
    41→    pub fn new() -> Self {
    42→        let mut model = Self {
    43→            universes: HashMap::new(),
    44→            domains: HashMap::new(),
    45→            admissible_sets: HashMap::new(),
    46→            transforms: HashMap::new(),
    47→            metadata: Metadata::new(),
    48→            #[cfg(feature = "z3-solver")]
    49→            prover: Prover::new(),
    50→        };
    51→
    52→        // Always create U0 (root universe)
