    59→    /// Add a projection universe (U1, U2, etc.)
    60→    ///
    61→    /// Returns the universe ID or an error if layer is invalid
    62→    pub fn add_universe(&mut self, layer: u8, name: String, description: String) -> Result<UniverseId, IdError> {
    63→        let universe = Universe::projection(layer, name, description)?;
    64→        let id = universe.id.clone();
    65→        self.universes.insert(id.clone(), universe);
    66→        Ok(id)
    67→    }
