   236→    /// Find Rust source files to analyze from config or graph metadata
   237→    fn find_rust_source_files(
   238→        &self,
   239→        config: &HashMap<String, String>,
   240→        graph: &SpecRepository,
   241→    ) -> Result<Vec<String>, String> {
   242→        // If source_files specified in config, use those
   243→        if let Some(files_str) = config.get("source_files") {
   244→            return Ok(files_str.split(',').map(|s| s.trim().to_string()).collect());
   245→        }
   246→
   247→        // Otherwise, find source files from graph nodes with source_file metadata
   248→        let mut source_files = HashSet::new();
   249→        for node in graph.list_nodes(None) {
   250→            // Note: graph nodes still use HashMap<String, String> for metadata
   251→            // so we use the string key directly
   252→            if let Some(source_file) = node.metadata.get(MetadataKey::SourceFile.as_str())
   253→                && source_file.ends_with(".rs") {
   254→                    source_files.insert(source_file.clone());
   255→                }
   256→        }
   257→
   258→        if source_files.is_empty() {
   259→            Err("No source files found in config or graph metadata".to_string())
   260→        } else {
   261→            Ok(source_files.into_iter().collect())
   262→        }
   263→    }
