   389→                kind: ConstraintKind::Universal,
   390→                description: Some(description_text),
   391→                metadata: Some(meta),
   392→                meta: Some(meta_with_desc),
   393→            });
   394→        }
   395→
   396→        // Pattern 4: "maximum N" / "maximum of N"
   397→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "maximum") {
   398→            let mut meta = ConstraintMetadata::new();
   399→            meta.set_pattern("maximum".to_string());
   400→            meta.set_value(max_value.to_string());
   401→            meta.set_source(text.to_string());
   402→
   403→            let description_text = format!("Maximum value: {}", max_value);
   404→            let mut meta_with_desc = meta.clone();
   405→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
