     9→/// Execute the Extract command in standalone mode
    10→pub fn execute_extract_standalone(
    11→    store: &mut Store,
    12→    source: String,
    13→    language: String,
    14→    min_confidence: f32,
    15→) -> Result<(), Box<dyn std::error::Error>> {
