    20→
    21→    // Detect language from file extension if not specified
    22→    let detected_language = if path.is_file() {
    23→        match path.extension().and_then(|s| s.to_str()) {
    24→            Some("rs") => if language == "architecture" { "architecture" } else { "rust" },
    25→            Some("proto") => "proto",
    26→            Some("md") => "markdown",
    27→            Some("php") => "php",
    28→            _ => &language,
    29→        }
    30→    } else {
    31→        &language
    32→    };
