    36→        match detected_language {
    37→            "rust" => RustExtractor::extract(path).map_err(|e| format!("Extraction failed: {}", e))?,
    38→            "proto" => ProtoExtractor::extract(path).map_err(|e| format!("Extraction failed: {}", e))?,
    39→            "markdown" => DocExtractor::extract(path).map_err(|e| format!("Extraction failed: {}", e))?,
    40→            "php" => PHPTestExtractor::extract(path).map_err(|e| format!("Extraction failed: {}", e))?,
    41→            "architecture" => ArchitectureExtractor::extract(path).map_err(|e| format!("Extraction failed: {}", e))?,
    42→            _ => {
    43→                eprintln!("Unsupported language: {}. Supported: rust, proto, markdown, php, architecture", language);
    44→                return Ok(());
    45→            }
    46→        }
    47→    } else if path.is_dir() {
    48→        // Extract from all supported files in directory recursively
    49→        use std::fs;
    50→        let mut all_specs = Vec::new();
    51→        for entry in fs::read_dir(path).map_err(|e| format!("Failed to read directory: {}", e))? {
    52→            let entry = entry.map_err(|e| format!("Failed to read entry: {}", e))?;
    53→            let entry_path = entry.path();
    54→            match entry_path.extension().and_then(|s| s.to_str()) {
    55→                Some("rs") if detected_language == "rust" || detected_language == "auto" => {
    56→                    match RustExtractor::extract(&entry_path) {
    57→                        Ok(specs) => all_specs.extend(specs),
    58→                        Err(e) => eprintln!("⚠️  Failed to extract from {:?}: {}", entry_path, e),
    59→                    }
    60→                }
    61→                Some("proto") if detected_language == "proto" || detected_language == "auto" => {
    62→                    match ProtoExtractor::extract(&entry_path) {
    63→                        Ok(specs) => all_specs.extend(specs),
    64→                        Err(e) => eprintln!("⚠️  Failed to extract from {:?}: {}", entry_path, e),
    65→                    }
    66→                }
    67→                Some("md") if detected_language == "markdown" || detected_language == "auto" => {
    68→                    match DocExtractor::extract(&entry_path) {
    69→                        Ok(specs) => all_specs.extend(specs),
    70→                        Err(e) => eprintln!("⚠️  Failed to extract from {:?}: {}", entry_path, e),
    71→                    }
    72→                }
    73→                Some("php") if detected_language == "php" || detected_language == "auto" => {
    74→                    match PHPTestExtractor::extract(&entry_path) {
    75→                        Ok(specs) => all_specs.extend(specs),
    76→                        Err(e) => eprintln!("⚠️  Failed to extract from {:?}: {}", entry_path, e),
    77→                    }
    78→                }
    79→                Some("rs") if detected_language == "architecture" => {
    80→                    match ArchitectureExtractor::extract(&entry_path) {
    81→                        Ok(specs) => all_specs.extend(specs),
    82→                        Err(e) => eprintln!("⚠️  Failed to extract architecture from {:?}: {}", entry_path, e),
    83→                    }
    84→                }
    85→                _ => {}
    86→            }
    87→        }
    88→        all_specs
    89→    } else {
    90→        eprintln!("❌ Source path not found: {}", source);
    91→        return Ok(());
    92→    };
    93→
    94→    // Filter by confidence and ingest into graph
    95→    let filtered: Vec<_> = specs.into_iter()
    96→        .filter(|s| s.confidence >= min_confidence)
    97→        .collect();
    98→
    99→    println!("📊 Extracted {} specifications (confidence >= {})\n", filtered.len(), min_confidence);
   100→

