     1→//! RootSpace (Ω): The root space from which projections originate
     2→//!
     3→//! Ω represents the collected evidence space - the set of artifacts, traces,
     4→//! and observations from which U0 (root specification) is constructed via
     5→//! inverse mappings.
     6→//!
     7→//! ## 3-Layer Structure
     8→//! - Layer 1: Identifier (`id`) - RootSpaceId (UUID-based)
     9→//! - Layer 2: Proof Data (`proof_data`) - snapshot integrity, trace provenance
    10→//! - Layer 3: Metadata (`meta`) - kind, snapshot_time, version, human-readable info
    11→
    12→use crate::formal::{IdError, MetadataKey};
    13→use serde::{Deserialize, Deserializer, Serialize, Serializer};
    14→use std::collections::HashMap;
    15→use std::fmt;
    16→use uuid::Uuid;
    17→
    18→// =============================================================================
    19→// Layer 1: RootSpaceId
    20→// =============================================================================
    21→
    22→/// Unique identifier for a RootSpace (UUID-based)
    23→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    24→pub struct RootSpaceId(String);
    25→
    26→impl RootSpaceId {
    27→    /// Create a new RootSpace ID (generates UUID)
    28→    pub fn new() -> Self {
    29→        Self(Uuid::new_v4().to_string())
    30→    }
    31→
    32→    /// Parse from string (validates UUID format)
    33→    pub fn parse(s: &str) -> Result<Self, IdError> {
    34→        Uuid::parse_str(s)
    35→            .map_err(|_| IdError::InvalidUuid(format!("Invalid UUID for RootSpaceId: {}", s)))?;
    36→        Ok(Self(s.to_string()))
    37→    }
    38→
    39→    /// Get the string representation
    40→    pub fn as_str(&self) -> &str {
    41→        &self.0
    42→    }
    43→}
    44→
    45→impl Default for RootSpaceId {
    46→    fn default() -> Self {
    47→        Self::new()
    48→    }
    49→}
    50→
    51→impl fmt::Display for RootSpaceId {
    52→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    53→        write!(f, "{}", self.0)
    54→    }
    55→}
    56→
    57→impl Serialize for RootSpaceId {
    58→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    59→    where
    60→        S: Serializer,
    61→    {
    62→        serializer.serialize_str(&self.0)
    63→    }
    64→}
    65→
    66→impl<'de> Deserialize<'de> for RootSpaceId {
    67→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    68→    where
    69→        D: Deserializer<'de>,
    70→    {
    71→        let s = String::deserialize(deserializer)?;
    72→        RootSpaceId::parse(&s).map_err(serde::de::Error::custom)
    73→    }
    74→}
    75→
    76→// =============================================================================
    77→// Layer 2: RootSpaceProofData
    78→// =============================================================================
    79→
    80→/// Proof-essential data for RootSpace
    81→///
    82→/// Contains only the data needed for formal verification and proofs.
    83→/// The Prover should only access this layer, never metadata.
