   118→}
   119→
   120→// =============================================================================
   121→// Layer 3: RootSpaceMetadata
   122→// =============================================================================
   123→
   124→/// Metadata for RootSpace with convenient accessors
   125→///
   126→/// Uses HashMap<String, String> internally for serialization compatibility,
