   175→
   176→    /// Generic get/insert for other metadata
   177→    pub fn get(&self, key: &MetadataKey) -> Option<&String> {
   178→        self.inner.get(key.as_str())
   179→    }
   180→
   181→    pub fn insert(&mut self, key: MetadataKey, value: String) {
   182→        self.inner.insert(key.as_str().to_string(), value);
   183→    }
   184→
   185→    pub fn inner(&self) -> &HashMap<String, String> {
   186→        &self.inner
   187→    }
   188→
   189→    pub fn inner_mut(&mut self) -> &mut HashMap<String, String> {
   190→        &mut self.inner
   191→    }
   192→}
   193→
   194→impl Default for RootSpaceMetadata {
   195→    fn default() -> Self {
   196→        Self::new()
