   211→
   212→// =============================================================================
   213→// RootSpaceKind
   214→// =============================================================================
   215→
   216→/// The kind of root space
   217→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
   218→pub enum RootSpaceKind {
   219→    /// A bundle of artifacts (code, tests, docs, protos, contracts, types)
   220→    /// collected at a point in time for inverse mapping
   221→    ArtifactBundle,
   222→
   223→    /// A trace of system behavior (execution logs, test results, runtime observations)
   224→    /// used for behavioral inference
