     1→/// Observer: obs_i (Omega -> Option Gamma_i)
     2→///
     3→/// An observer examines a root space (Omega) and, if the root space matches
     4→/// the observer's expected kind, extracts an artifact space (Gamma_i) from it.
     5→///
     6→/// This is the first half of the projection composition:
     7→///   proj_i = obs_i >> extract_i
     8→///
     9→/// Each observer is specialized for a particular root space kind:
    10→/// - ArtifactBundleObserver: observes artifact bundle root spaces
    11→/// - TraceObserver: observes behavioral trace root spaces
    12→/// - FileSystemObserver: observes file system root spaces directly
    13→use crate::formal::projection::{RootSpace, RootSpaceKind, ArtifactSpace, ArtifactKind};
    14→use crate::formal::universe::UniverseId;
    15→
    16→/// Observer trait: examines a root space and produces an artifact space.
    17→///
    18→/// Implements obs_i: Omega -> Option<Gamma_i>
    19→/// Returns None when the root space kind does not match the observer's expectation.
    20→pub trait Observer {
    21→    /// Attempt to observe an artifact space from the given root space.
    22→    ///
    23→    /// The layer_id parameter specifies which universe layer is being observed,
    24→    /// allowing observers to filter or select artifacts based on layer metadata.
    25→    ///
    26→    /// Returns `Some(ArtifactSpace)` if the root space kind matches and
    27→    /// artifact information can be extracted from metadata.
    28→    /// Returns `None` if the root space kind does not match.
    29→    fn observe(&self, root: &RootSpace, layer_id: &UniverseId) -> Option<ArtifactSpace>;
    30→
    31→    /// The kind of artifact this observer produces.
    32→    fn artifact_kind(&self) -> ArtifactKind;
    33→}
    34→
    35→/// Observer for artifact bundle root spaces.
    36→///
    37→/// Expects `RootSpaceKind::ArtifactBundle` and extracts artifact information
    38→/// from the root space metadata fields: "content_value" and "source".
    39→pub struct ArtifactBundleObserver {
    40→    expected_artifact_kind: ArtifactKind,
    41→}
    42→
    43→impl ArtifactBundleObserver {
    44→    pub fn new(expected_artifact_kind: ArtifactKind) -> Self {
    45→        Self { expected_artifact_kind }
    46→    }
    47→}
    48→
    49→impl Observer for ArtifactBundleObserver {
    50→    fn observe(&self, root: &RootSpace, _layer_id: &UniverseId) -> Option<ArtifactSpace> {
    51→        if root.kind() != Some(RootSpaceKind::ArtifactBundle) {
    52→            return None;
    53→        }
    54→
    55→        let inner = root.meta.inner();
    56→        let content = inner.get("content_value").cloned().unwrap_or_default();
    57→        let source = inner.get("source").cloned()
    58→            .unwrap_or_else(|| format!("artifact_bundle:{}", root.id));
    59→
    60→        Some(ArtifactSpace::from_text(self.expected_artifact_kind, content, source))
    61→    }
    62→
    63→    fn artifact_kind(&self) -> ArtifactKind {
    64→        self.expected_artifact_kind
    65→    }
    66→}
    67→
    68→/// Observer for behavioral trace root spaces.
    69→///
    70→/// Expects `RootSpaceKind::Trace` and extracts trace data as an artifact space.
    71→/// Traces represent runtime behavior observations (logs, execution traces, etc.).
    72→pub struct TraceObserver {
    73→    expected_artifact_kind: ArtifactKind,
    74→}
    75→
    76→impl TraceObserver {
    77→    pub fn new(expected_artifact_kind: ArtifactKind) -> Self {
    78→        Self { expected_artifact_kind }
    79→    }
    80→}
    81→
    82→impl Observer for TraceObserver {
    83→    fn observe(&self, root: &RootSpace, _layer_id: &UniverseId) -> Option<ArtifactSpace> {
    84→        if root.kind() != Some(RootSpaceKind::Trace) {
    85→            return None;
    86→        }
    87→
    88→        let inner = root.meta.inner();
    89→        let content = inner.get("trace_data").cloned()
    90→            .or_else(|| inner.get("content_value").cloned())
    91→            .unwrap_or_default();
    92→        let source = inner.get("source").cloned()
    93→            .unwrap_or_else(|| format!("trace:{}", root.id));
    94→
    95→        Some(ArtifactSpace::from_text(self.expected_artifact_kind, content, source))
    96→    }
    97→
    98→    fn artifact_kind(&self) -> ArtifactKind {
    99→        self.expected_artifact_kind
   100→    }
   101→}
