    22→    /// API specification (OpenAPI, gRPC proto, etc.)
    23→    APISpec,
    24→    /// Source code implementation
    25→    SourceCode,
    26→    /// Test code (unit, integration, E2E, property-based)
    27→    TestCode,
    28→    /// Type definitions (TypeScript .d.ts, Rust trait, etc.)
    29→    TypeDefinitions,
    30→    /// Formal specification (TLA+, Alloy, Lean4, etc.)
    31→    FormalSpec,
    32→}
    33→
    34→impl fmt::Display for ArtifactKind {
    35→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    36→        match self {
    37→            ArtifactKind::RequirementsDoc => write!(f, "requirements_doc"),
    38→            ArtifactKind::APISpec => write!(f, "api_spec"),
    39→            ArtifactKind::SourceCode => write!(f, "source_code"),
