    83→impl Serialize for ArtifactSpaceId {
    84→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    85→    where
    86→        S: serde::Serializer,
    87→    {
    88→        serializer.serialize_str(&self.0)
    89→    }
    90→}
    91→
    92→impl<'de> Deserialize<'de> for ArtifactSpaceId {
