     1→/// Integration test for projection layer (following plan specification)
     2→///
     3→/// Tests the complete projection composition: proj_i = obs_i >> extract_i
     4→
     5→use spec_core::formal::projection::{
     6→    RootSpace, ArtifactSpace, ArtifactKind,
     7→    Observer, ArtifactBundleObserver,
     8→    Projection, Extractor,
     9→};
    10→use spec_core::formal::universe::UniverseId;
    11→use spec_core::InferredSpecification;
    12→
    13→/// Simple test extractor that extracts lines as specs
    14→struct LineExtractor;
    15→
    16→impl Extractor<String> for LineExtractor {
    17→    fn extract(&self, artifact: &ArtifactSpace) -> Vec<String> {
    18→        match artifact.as_text() {
    19→            Some(text) => text.lines().map(|s| s.to_string()).collect(),
    20→            None => Vec::new(),
    21→        }
    22→    }
    23→}
    24→
    25→#[test]
    26→fn test_projection_composition() {
    27→    // Create artifact bundle root using metadata-based design
    28→    let mut root = RootSpace::new_artifact_bundle();
    29→
    30→    // Add artifact content to metadata
    31→    root.meta.inner_mut().insert(
    32→        "content_value".to_string(),
    33→        "line1\nline2\nline3".to_string(),
    34→    );
    35→    root.meta.inner_mut().insert(
    36→        "source".to_string(),
    37→        "test.txt".to_string(),
    38→    );
    39→
    40→    // Create observer
    41→    let observer = ArtifactBundleObserver::new(ArtifactKind::SourceCode);
    42→
    43→    // Create extractor
    44→    let extractor = LineExtractor;
    45→
    46→    // Create projection composition
    47→    let layer_id = UniverseId::projection(3).unwrap();
    48→    let projection = Projection::new(observer, extractor, layer_id);
    49→
    50→    // Execute: obs >> extract
    51→    let result: Vec<String> = projection.project(&root);
    52→
    53→    // Verify composition worked
    54→    assert_eq!(result.len(), 3);
    55→    assert_eq!(result[0], "line1");
    56→    assert_eq!(result[1], "line2");
    57→    assert_eq!(result[2], "line3");
    58→}
    59→
    60→#[test]
    61→fn test_projection_with_none_observer() {
    62→    // Create trace root (wrong kind for ArtifactBundleObserver)
    63→    let root = RootSpace::new_trace();
    64→
    65→    // Create observer expecting artifact bundle
    66→    let observer = ArtifactBundleObserver::new(ArtifactKind::SourceCode);
    67→    let extractor = LineExtractor;
    68→
    69→    let layer_id = UniverseId::projection(3).unwrap();
    70→    let projection = Projection::new(observer, extractor, layer_id);
    71→
    72→    // Execute - should return empty Vec because observer returns None
    73→    let result: Vec<String> = projection.project(&root);
    74→    assert!(result.is_empty());
    75→}
    76→
    77→#[test]
    78→fn test_observer_returns_artifact_space() {
    79→    let mut root = RootSpace::new_artifact_bundle();
    80→
    81→    root.meta.inner_mut().insert(
    82→        "content_value".to_string(),
    83→        "test content".to_string(),
    84→    );
    85→
    86→    let observer = ArtifactBundleObserver::new(ArtifactKind::SourceCode);
    87→    let layer_id = UniverseId::projection(3).unwrap();
    88→
    89→    // Call observer directly
    90→    let artifact = observer.observe(&root, &layer_id);
    91→
    92→    assert!(artifact.is_some());
    93→    let artifact = artifact.unwrap();
    94→    assert_eq!(artifact.kind(), Some(ArtifactKind::SourceCode));
    95→    assert_eq!(artifact.as_text(), Some(&"test content".to_string()));
    96→}
