     1→use std::path::PathBuf;
     2→
     3→/// Storage type detected in the project
     4→#[derive(Debug, Clone, PartialEq)]
     5→pub enum StorageType {
     6→    /// Directory-based storage (.spec/nodes/*.yaml + .spec/edges.yaml)
     7→    Directory(PathBuf),
     8→    /// File-based storage (.spec/specs.json)
     9→    File(PathBuf),
    10→}
    11→
    12→/// Find .spec directory by walking up from current directory
    13→///
    14→/// Searches for a project-local .spec directory by traversing
    15→/// up the directory tree from the current working directory.
    16→///
    17→/// Returns Some(path) if found, None otherwise.
    18→pub fn find_spec_dir() -> Option<PathBuf> {
    19→    let mut current = std::env::current_dir().ok()?;
    20→    loop {
    21→        let spec_dir = current.join(".spec");
    22→        if spec_dir.exists() && spec_dir.is_dir() {
    23→            return Some(spec_dir);
    24→        }
    25→        if !current.pop() {
    26→            break;
    27→        }
    28→    }
    29→    None
    30→}
    31→
    32→/// Detect storage type in the project
    33→///
    34→/// Checks for directory-based storage first (.spec/nodes/), then falls back
    35→/// to file-based storage (.spec/specs.json).
    36→///
    37→/// Returns Some(StorageType) if storage is found, None otherwise.
    38→pub fn detect_storage_type() -> Option<StorageType> {
    39→    let spec_dir = find_spec_dir()?;
    40→
    41→    // Prioritize directory-based storage (newer format)
    42→    let nodes_dir = spec_dir.join("nodes");
    43→    if nodes_dir.exists() && nodes_dir.is_dir() {
    44→        return Some(StorageType::Directory(spec_dir));
    45→    }
    46→
    47→    // Fall back to file-based storage
    48→    let spec_file = spec_dir.join("specs.json");
    49→    if spec_file.exists() {
    50→        return Some(StorageType::File(spec_file));
    51→    }
    52→
    53→    None
    54→}
    55→
    56→/// Find .spec/specs.json by walking up from current directory
    57→///
    58→/// Searches for a project-local .spec/specs.json file by traversing
    59→/// up the directory tree from the current working directory.
    60→///
    61→/// Returns Some(path) if found, None otherwise.
    62→pub fn find_spec_file() -> Option<PathBuf> {
    63→    let spec_dir = find_spec_dir()?;
    64→    let spec_file = spec_dir.join("specs.json");
    65→    if spec_file.exists() {
    66→        Some(spec_file)
    67→    } else {
    68→        None
    69→    }
    70→}
    71→
    72→/// Check if standalone mode should be used
    73→///
    74→/// Returns true if a project-local .spec directory is found.
    75→pub fn should_use_standalone_mode() -> bool {
    76→    find_spec_dir().is_some()
    77→}
    78→
    79→/// Get the spec file path, or return None if not in a spec-managed project
    80→pub fn get_spec_file_path() -> Option<PathBuf> {
    81→    find_spec_file()
    82→}
    83→
    84→#[cfg(test)]
    85→mod tests {
    86→    use super::*;
    87→
    88→    #[test]
    89→    fn test_find_spec_dir() {
    90→        // This test assumes running in spec-oracle project
    91→        let path = find_spec_dir();
    92→        assert!(path.is_some(), "Should find .spec directory in project");
    93→
    94→        if let Some(p) = path {
    95→            assert!(p.ends_with(".spec"));
    96→        }
    97→    }
    98→
