    14→/// Unified storage interface supporting both file-based and directory-based storage
    15→pub enum Store {
    16→    /// File-based storage (.spec/specs.json)
    17→    File(FileStore),
    18→    /// Directory-based storage (.spec/nodes/*.yaml + .spec/edges.yaml)
    19→    Directory(DirectoryStore),
    20→}
    21→
    22→impl Store {
    23→    /// Load specification repository from storage
    24→    pub fn load(&self) -> Result<SpecRepository, StoreError> {
    25→        match self {
    26→            Store::File(store) => store.load(),
    27→            Store::Directory(store) => store.load(),
    28→        }
    29→    }
    30→
    31→    /// Save specification repository to storage
    32→    pub fn save(&self, repo: &SpecRepository) -> Result<(), StoreError> {
    33→        match self {
    34→            Store::File(store) => store.save(repo),
    35→            Store::Directory(store) => store.save(repo),
    36→        }
    37→    }
    38→
    39→    /// Create a Store from a file path
    40→    pub fn from_file(path: impl AsRef<Path>) -> Self {
    41→        Store::File(FileStore::new(path))
    42→    }
    43→
    44→    /// Create a Store from a directory path
    45→    pub fn from_directory(path: impl AsRef<Path>) -> Self {
    46→        Store::Directory(DirectoryStore::new(path))
    47→    }
    48→}
