    50→/// File-based persistence for the specification repository.
    51→pub struct FileStore {
    52→    path: PathBuf,
    53→}
    54→
    55→impl FileStore {
    56→    pub fn new(path: impl AsRef<Path>) -> Self {
    57→        Self {
    58→            path: path.as_ref().to_path_buf(),
    59→        }
    60→    }
    61→
    62→    pub fn load(&self) -> Result<SpecRepository, StoreError> {
    63→        if !self.path.exists() {
    64→            return Ok(SpecRepository::new());
    65→        }
    66→        let data = std::fs::read_to_string(&self.path)?;
    67→        let mut repo: SpecRepository = serde_json::from_str(&data)?;
    68→        repo.rebuild_indices();
    69→        Ok(repo)
    70→    }
    71→
    72→    pub fn save(&self, repo: &SpecRepository) -> Result<(), StoreError> {
    73→        if let Some(parent) = self.path.parent() {
    74→            std::fs::create_dir_all(parent)?;
    75→        }
    76→        let data = serde_json::to_string_pretty(repo)?;
    77→        std::fs::write(&self.path, data)?;
    78→        Ok(())
    79→    }
    80→}
