   148→                let entry = entry?;
   149→                let path = entry.path();
   150→                if path.extension().and_then(|s| s.to_str()) == Some("yaml") {
   151→                    let content = std::fs::read_to_string(&path)?;
   152→                    let node: crate::data::SpecNodeData = serde_yaml::from_str(&content)?;
   153→                    repo.add_node_from_loaded(node);
